[TFMDescription("Converts values to integer")]
class TFMLogicContextToInteger extends TFMLogicContextTools
{

}

Method.Source:
public static TFMLogicContextToInteger Construct()
{
    return new TFMLogicContextToInteger();
}

protected void new()
{
    super();
    inputTypes.add(TFMLogicContextTypes::String);
    inputTypes.add(TFMLogicContextTypes::Boolean);
    inputTypes.add(TFMLogicContextTypes::Decimal);
    outputType = TFMLogicContextTypes::Integer;
    noOfInput = 1;
    categories.add("@TFM:TypeConversion");
}

public Object process()
{
    Object ret;


    return ret;
}

public anytype evaluate(TFMLogicContext _context)
{
    anytype         ret;
    SetEnumerator   sEnum;
    TFMCondition    condition;
    str             value;

    if (children == null)
    {
        return 0;
    }

    sEnum = children.getEnumerator();

    while (sEnum.moveNext())
    {
        condition = sEnum.current();
        ret = condition.evaluate(_context);
    }

    value = strLwr(strLRTrim(any2Str(ret)));

    switch (value)
    {
        case '':
        case 'false':
        case 'no':
            return 0;

        case 'true':
        case 'yes':
            return 1;
    }

    // Numeric values and numeric strings
    int result = any2Int(ret);

    // If conversion produced a non-zero number, use it
    if (result != 0)
    {
        return result;
    }

    // Any zero-like numeric value
    if (value == '0' || value == '0.0')
    {
        return 0;
    }

    // Any other text
    return 1;
}
